-- STET Paper II has its own topic list. The first 15 topics stay on Paper I.

update public.topics
set paper = 'PAPER_I'
where slug in (
  'naad-shruti-swar-saptak',
  'shruti-swar-vyavastha-thaat',
  'raag-vargikaran',
  'gaan-evam-prabandh',
  'gharana-gayan-shailiyan',
  'vaidik-sangeet',
  'uttar-bharatiya-karnatak-sangeet',
  'sangitik-shabdavali',
  'vadya-vargikaran-vrind-vadan',
  'pashchatya-sangeet',
  'pramukh-sangeetagya',
  'sangitik-granth',
  'nirdharit-raag',
  'taal-evam-lay',
  'swaralipi-raag-tulana-loksangeet'
);

on conflict (id) do update set
  name = excluded.name,
  slug = excluded.slug,
  display_order = excluded.display_order,
  paper = excluded.paper,
  exam = excluded.exam;

on conflict (id) do update set name = excluded.name, slug = excluded.slug, display_order = excluded.display_order;
